use super::*;

// Generated by firmware-common's osg_event_stream_test --vectors, using the
// actual collector and formatter. This checks the cross-language wire boundary.
#[test]
fn compiled_firmware_vectors_preserve_pages_loss_capture_and_new_scope_recovery(){
    let mut decoder=Decoder::new(77);let received=Instant::now();
    let frames=include_str!("fixtures/events-push.jsonl").lines().map(|line|
        decoder.decode(line,received).unwrap_or_else(|error|panic!("{error}: {line}")))
        .collect::<Vec<_>>();
    assert_eq!(frames.len(),9);
    for(index,frame)in frames.iter().enumerate(){assert_eq!(frame.sequence,index as u32+1);assert_eq!(frame.received_at,received);}
    assert_eq!(frames[0].kind,Kind::Baseline);assert_eq!(frames[0].cursor,0);
    assert_eq!(frames[1].state["events"].as_array().unwrap().len(),16);
    assert_eq!(frames[1].state["more"],true);
    let encoder=frames[2].state["events"].as_array().unwrap();
    assert_eq!(encoder.len(),2);assert_eq!(encoder[0]["pressed"],true);assert_eq!(encoder[1]["pressed"],false);
    assert_eq!(encoder[0]["control"],encoder[1]["control"]);
    assert_eq!(encoder[0]["capturedAtMs"],encoder[1]["capturedAtMs"]);
    assert_eq!(frames[3].reason.as_deref(),Some("axes"));
    assert_eq!(frames[4].reason.as_deref(),Some("eventGap"));assert_eq!(frames[4].cursor,84);
    assert!(frames[4].state.get("events").is_none(),"loss baseline must not replay retained history");
    assert_eq!(frames[5].stream,5);assert_eq!(frames[5].kind,Kind::Loss);
    assert!(frames[6].exhausted);assert_eq!(frames[6].reason.as_deref(),Some("streamExhausted"));
    assert_eq!(frames[7].stream,6);assert!(!frames[7].exhausted);
    assert_eq!(frames[8].stream,6);assert_eq!(frames[8].cursor,1);
    assert_eq!(frames[8].state["events"][0]["pressed"],true);
}
